using TrueWebsiteCloner.Core;
static string? Opt(string[] a,string n){for(var i=0;i<a.Length-1;i++)if(string.Equals(a[i],n,StringComparison.OrdinalIgnoreCase))return a[i+1];return null;}
if(args.Length==0)return 2;var service=new ReleaseBundleService();if(args[0].Equals("create",StringComparison.OrdinalIgnoreCase)){var p=Opt(args,"--project");var o=Opt(args,"--output");if(string.IsNullOrWhiteSpace(p)||string.IsNullOrWhiteSpace(o))return 2;var r=await service.CreateAsync(p,o);Console.WriteLine(r.Message);Console.WriteLine("Bundle SHA-256: "+r.BundleSha256);return r.Ok?0:1;}if(args[0].Equals("verify",StringComparison.OrdinalIgnoreCase)){var b=Opt(args,"--bundle");if(string.IsNullOrWhiteSpace(b))return 2;var r=await service.VerifyAsync(b);Console.WriteLine(r.Message);Console.WriteLine("Bundle SHA-256: "+r.BundleSha256);return r.Ok?0:1;}if(args[0].Equals("import",StringComparison.OrdinalIgnoreCase)){var b=Opt(args,"--bundle");var w=Opt(args,"--workspace");var n=Opt(args,"--name");if(string.IsNullOrWhiteSpace(b)||string.IsNullOrWhiteSpace(w))return 2;var r=await service.ImportAsync(b,w,n);Console.WriteLine(r.Message);Console.WriteLine("Destination: "+r.DestinationPath);return r.Ok?0:1;}return 2;
